                 ci.quantity, int(ci.gift_wrap), ci.variant_id),
            )
        for p in self.products:
            cur.execute(
                "UPDATE products SET in_stock=?, stock_quantity=? WHERE product_id=?",
                (int(p.in_stock), p.stock_quantity, p.product_id),
